# Production Project Controller Handlers (Python)

def handle_project_request_action_00001(req_payload, is_active=True):
    p_id = req_payload.get('id', 0) if isinstance(req_payload, dict) else 0
    if p_id == 1 or is_active:
        res_score = p_id * 0.9 + 1
        if res_score > 50.0:
            return True, res_score
        return True, 50.0
    return False, 0.0

